export const sanitizeDataForFirestore = (obj: any): any => {
  if (obj === null || obj === undefined) return null;
  if (Array.isArray(obj)) {
    return obj.map(item => sanitizeDataForFirestore(item));
  }
  if (typeof obj === 'object') {
    const cleaned: any = {};
    for (const key of Object.keys(obj)) {
      const val = obj[key];
      if (val !== undefined) {
        cleaned[key] = sanitizeDataForFirestore(val);
      }
    }
    return cleaned;
  }
  return obj;
};

// --- Browser Direct Print Integration & Dynamic Dual-Layout Engine ---
export const triggerBrowserPrint = (doc: any) => {
  const pdfBlob = doc.output('blob');
  const pdfUrl = URL.createObjectURL(pdfBlob);
  
  const iframeId = 'souplastic-print-iframe';
  let iframe = document.getElementById(iframeId) as HTMLIFrameElement;
  if (iframe) {
    document.body.removeChild(iframe);
  }
  
  iframe = document.createElement('iframe');
  iframe.id = iframeId;
  iframe.style.position = 'fixed';
  iframe.style.right = '0';
  iframe.style.bottom = '0';
  iframe.style.width = '0';
  iframe.style.height = '0';
  iframe.style.border = 'none';
  iframe.style.zIndex = '-9999';
  iframe.src = pdfUrl;
  
  document.body.appendChild(iframe);
  
  iframe.onload = () => {
    try {
      iframe.contentWindow?.focus();
      iframe.contentWindow?.print();
    } catch (err) {
      console.error("Erro na impressão direta:", err);
      window.open(pdfUrl, '_blank');
    }
  };
};

export const drawSingleLabel = async (
  doc: any,
  lbl: any,
  order: any,
  xOffset: number,
  labelWidth: number,
  labelHeight: number,
  qrSize: number,
  qrMarginRight: number,
  yOffset: number = 0,
  config: any = {}
) => {
  // Read font sizes from config, fallback to defaults or sensible values
  const clientFontSizeCfg = config.clientFontSize || 10;
  const productFontSizeCfg = config.productFontSize || 8;

  // 1. Determine margin based on the physical size of this individual label
  // At least 5mm for larger labels, otherwise 3mm for compact ones.
  const margin = (labelWidth >= 60 && labelHeight >= 40) ? 5 : 3;
  
  // 1.1 Calculate printable boundaries inside the label
  const px = xOffset + margin;
  const py = yOffset + margin;
  const pw = labelWidth - 2 * margin;
  const ph = labelHeight - 2 * margin;
  
  // 2. Banner/Header Height (Scales elegantly with height)
  const headerH = Math.max(4, Math.min(10, ph * 0.16));
  
  // Draw primary dark banner background
  doc.setFillColor(15, 23, 42); 
  doc.rect(px, py, pw, headerH, 'F');
  
  // Print Title centered in the banner - Auto shrink font size to fit width perfectly
  doc.setTextColor(255, 255, 255);
  doc.setFont('Helvetica', 'bold');
  const titleText = 'SOUPLASTIC - IDENTIFICADO';
  let titleFontSize = Math.max(4.5, Math.min(8.5, headerH * 1.1));
  doc.setFontSize(titleFontSize);
  let titleWidth = doc.getTextWidth(titleText);
  while (titleWidth > pw - 2 && titleFontSize > 3) {
    titleFontSize -= 0.3;
    doc.setFontSize(titleFontSize);
    titleWidth = doc.getTextWidth(titleText);
  }
  doc.text(titleText, px + pw / 2, py + headerH / 2 + (titleFontSize * 0.3527) / 2, { align: 'center' });
  
  // Draw light border frame around active contents below the header
  doc.setDrawColor(226, 232, 240); 
  doc.setLineWidth(0.25);
  doc.rect(px, py + headerH, pw, ph - headerH);
  
  // Determine if this is a narrow vertical portrait label or horizontal landscape label
  const isPortraitLabel = labelHeight > labelWidth;
  
  if (isPortraitLabel) {
    // --- PORTRAIT LAYOUT (QR Code in middle, text details top/bottom) ---
    const totalRemainingH = ph - headerH;
    
    // Max QR Code size can be up to 70% of total remaining height, capped by printable width (minus small left/right margin)
    // We prioritize using config.qrSize unless it physically doesn't fit on the label.
    const maxQrPossible = Math.min(pw - 1.0, totalRemainingH * 0.65);
    const activeQrSize = Math.min(qrSize, maxQrPossible);
    
    // Center QR Code horizontally
    const qx = px + (pw - activeQrSize) / 2;
    
    // Divide remaining height: 32% for client name area, 68% for product description area below
    const remainingTextHeight = totalRemainingH - activeQrSize;
    const clientAreaH = Math.max(4, remainingTextHeight * 0.32);
    const spaceBelow = Math.max(4, remainingTextHeight - clientAreaH);
    
    const clientY = py + headerH;
    const qy = clientY + clientAreaH;
    
    // 1. Render Client Name (centered horizontally and vertically inside clientAreaH)
    const clientTextFull = String(order.clientName || 'SOUPLASTIC').trim();
    const firstWordClient = clientTextFull.split(/\s+/)[0].toUpperCase();
    
    let clientFontSize = clientFontSizeCfg;
    doc.setFont('Helvetica', 'bold');
    doc.setFontSize(clientFontSize);
    let clientWidth = doc.getTextWidth(firstWordClient);
    
    // Auto shrink client font size if it wider than printable area
    while (clientWidth > pw - 2 && clientFontSize > 4) {
      clientFontSize -= 0.5;
      doc.setFontSize(clientFontSize);
      clientWidth = doc.getTextWidth(firstWordClient);
    }
    doc.setTextColor(15, 23, 42);
    doc.text(firstWordClient, px + pw / 2, clientY + clientAreaH / 2 + (clientFontSize * 0.3527) / 2.5, { align: 'center' });
    
    // 2. Render QR Code
    const qrUrl = await QRCode.toDataURL(lbl.id, { margin: 1, width: 120 });
    doc.addImage(qrUrl, 'PNG', qx, qy, activeQrSize, activeQrSize);
    
    // 3. Render Product Description below QR Code
    doc.setFont('Helvetica', 'bold');
    let productFontSize = productFontSizeCfg;
    doc.setFontSize(productFontSize);
    doc.setTextColor(15, 23, 42);
    
    let parts = doc.splitTextToSize(String(lbl.productName || '').toUpperCase(), pw - 2);
    let lineHeightMultiplier = 1.15;
    let totalHeightMm = parts.length * productFontSize * 0.352778 * lineHeightMultiplier;
    
    // Auto shrink product details font size if height overflows the bottom margins
    while ((totalHeightMm > spaceBelow - 0.8) && productFontSize > 3.5) {
      productFontSize -= 0.5;
      doc.setFontSize(productFontSize);
      parts = doc.splitTextToSize(String(lbl.productName || '').toUpperCase(), pw - 2);
      totalHeightMm = parts.length * productFontSize * 0.352778 * lineHeightMultiplier;
    }
    
    const textStartY = qy + activeQrSize + (spaceBelow - totalHeightMm) / 2 + (productFontSize * 0.352778 * lineHeightMultiplier) / 2;
    doc.text(parts, px + pw / 2, textStartY, { align: 'center' });
    
  } else {
    // --- LANDSCAPE LAYOUT (QR Code on right, text block on left) ---
    const totalRemainingH = ph - headerH;
    
    // Cap QR Code size dynamically. Prioritize user qrSize but ensure physical margins are safe.
    const maxQrPossible = Math.min(pw * 0.45, totalRemainingH - 1.0);
    const activeQrSize = Math.min(qrSize, maxQrPossible);
    
    // QR Code horizontal position (aligned to the right side of the printable area)
    const safeQrMarginRight = Math.min(qrMarginRight, pw - activeQrSize - 1.0);
    const qx = px + pw - activeQrSize - safeQrMarginRight;
    
    // Center QR Code vertically in the remaining space below header
    const qy = py + headerH + (totalRemainingH - activeQrSize) / 2;
    
    // Render QR Code image
    const qrUrl = await QRCode.toDataURL(lbl.id, { margin: 1, width: 120 });
    doc.addImage(qrUrl, 'PNG', qx, qy, activeQrSize, activeQrSize);
    
    // Left column text bounds (taking remaining horizontal and vertical spacing)
    const tx = px + 1.0;
    const maxTextW = qx - tx - 2.5;
    
    const clientAreaH = totalRemainingH * 0.30;
    const spaceBelow = totalRemainingH - clientAreaH;
    
    const clientY = py + headerH;
    const productY = clientY + clientAreaH;
    
    // 1. Render Client Name inside left column
    const clientTextFull = String(order.clientName || 'SOUPLASTIC').trim();
    const firstWordClient = clientTextFull.split(/\s+/)[0].toUpperCase();
    
    let clientFontSize = clientFontSizeCfg;
    doc.setFont('Helvetica', 'bold');
    doc.setFontSize(clientFontSize);
    let clientWidth = doc.getTextWidth(firstWordClient);
    while (clientWidth > maxTextW && clientFontSize > 4) {
      clientFontSize -= 0.5;
      doc.setFontSize(clientFontSize);
      clientWidth = doc.getTextWidth(firstWordClient);
    }
    doc.setTextColor(15, 23, 42);
    doc.text(firstWordClient, tx + maxTextW / 2, clientY + clientAreaH / 2 + (clientFontSize * 0.3527) / 2.5, { align: 'center' });
    
    // 2. Render Product Description inside left column (wrapped)
    doc.setFont('Helvetica', 'bold');
    let productFontSize = productFontSizeCfg;
    doc.setFontSize(productFontSize);
    doc.setTextColor(15, 23, 42);
    
    let parts = doc.splitTextToSize(String(lbl.productName || '').toUpperCase(), maxTextW);
    let lineHeightMultiplier = 1.15;
    let totalHeightMm = parts.length * productFontSize * 0.352778 * lineHeightMultiplier;
    
    // Auto shrink product font if it overflows left height
    while ((totalHeightMm > spaceBelow - 0.8) && productFontSize > 3.5) {
      productFontSize -= 0.5;
      doc.setFontSize(productFontSize);
      parts = doc.splitTextToSize(String(lbl.productName || '').toUpperCase(), maxTextW);
      totalHeightMm = parts.length * productFontSize * 0.352778 * lineHeightMultiplier;
    }
    
    const textStartY = productY + (spaceBelow - totalHeightMm) / 2 + (productFontSize * 0.352778 * lineHeightMultiplier) / 2;
    doc.text(parts, tx + maxTextW / 2, textStartY, { align: 'center' });
  }
};

export const generateLabelsPDFDoc = async (
  lbls: any[], 
  order: any, 
  config: {
    labelWidth: number;
    labelHeight: number;
    columnLayout?: 'single' | 'double';
    columnGap?: number;
    qrSize: number;
    qrMarginRight: number;
    topMargin?: number;
    pdfPageOrientation?: 'landscape' | 'portrait';
    clientFontSize?: number;
    productFontSize?: number;
  }
) => {
  const { 
    labelWidth = 50, 
    labelHeight = 30, 
    columnLayout = 'double', 
    columnGap = 2, 
    qrSize = 20, 
    qrMarginRight = 5,
    topMargin = 0,
    pdfPageOrientation = 'landscape'
  } = config;
  
  // To avoid jsPDF auto-swapping custom dimensions (which rotates labels unpredictably),
  // we align active dimensions correctly to match portrait/landscape representation.
  let activeWidth = labelWidth;
  let activeHeight = labelHeight;
  
  if (pdfPageOrientation === 'portrait') {
    activeWidth = Math.min(labelWidth, labelHeight);
    activeHeight = Math.max(labelWidth, labelHeight);
  } else {
    activeWidth = Math.max(labelWidth, labelHeight);
    activeHeight = Math.min(labelWidth, labelHeight);
  }
  
  const isDouble = columnLayout === 'double';
  const pageWidth = activeWidth;
  const pageHeight = isDouble ? (activeHeight * 2 + columnGap) : activeHeight;
  
  // We establish orientation exactly matching the final pageWidth and pageHeight aspect ratio.
  const orientation = pageWidth >= pageHeight ? 'l' : 'p';
  
  const doc = new jsPDF({
    orientation: orientation,
    unit: 'mm',
    format: [pageWidth, pageHeight]
  }) as any;
  
  if (isDouble) {
    for (let index = 0; index < lbls.length; index += 2) {
      if (index > 0) {
        doc.addPage([pageWidth, pageHeight], orientation);
      }
      
      const topLbl = lbls[index];
      await drawSingleLabel(doc, topLbl, order, 0, activeWidth, activeHeight, qrSize, qrMarginRight, 0 + topMargin, config);
      
      if (index + 1 < lbls.length) {
        const bottomLbl = lbls[index + 1];
        const bottomOffset = activeHeight + columnGap;
        await drawSingleLabel(doc, bottomLbl, order, 0, activeWidth, activeHeight, qrSize, qrMarginRight, bottomOffset + topMargin, config);
      }
    }
  } else {
    for (let index = 0; index < lbls.length; index++) {
      if (index > 0) {
        doc.addPage([pageWidth, pageHeight], orientation);
      }
      
      const lbl = lbls[index];
      await drawSingleLabel(doc, lbl, order, 0, activeWidth, activeHeight, qrSize, qrMarginRight, topMargin, config);
    }
  }
  
  return doc;
};

// --- Fullscreen Utility ---
const FullscreenButton = () => {
  const [isFullscreen, setIsFullscreen] = useState(!!document.fullscreenElement);

  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    document.addEventListener('webkitfullscreenchange', handleFullscreenChange);
    document.addEventListener('mozfullscreenchange', handleFullscreenChange);
    document.addEventListener('MSFullscreenChange', handleFullscreenChange);
    return () => {
      document.removeEventListener('fullscreenchange', handleFullscreenChange);
      document.removeEventListener('webkitfullscreenchange', handleFullscreenChange);
      document.removeEventListener('mozfullscreenchange', handleFullscreenChange);
      document.removeEventListener('MSFullscreenChange', handleFullscreenChange);
    };
  }, []);

  const toggleFullscreen = () => {
    try {
      if (!document.fullscreenElement) {
        localStorage.setItem('souplastic_fullscreen_intent', 'true');
        const docElm = document.documentElement as any;
        if (docElm.requestFullscreen) {
          docElm.requestFullscreen();
        } else if (docElm.mozRequestFullScreen) {
          docElm.mozRequestFullScreen();
        } else if (docElm.webkitRequestFullScreen) {
          docElm.webkitRequestFullScreen();
        } else if (docElm.msRequestFullscreen) {
          docElm.msRequestFullscreen();
        }
      } else {
        localStorage.setItem('souplastic_fullscreen_intent', 'false');
        if (document.exitFullscreen) {
          document.exitFullscreen();
        } else if ((document as any).mozCancelFullScreen) {
          (document as any).mozCancelFullScreen();
        } else if ((document as any).webkitExitFullscreen) {
          (document as any).webkitExitFullscreen();
        } else if ((document as any).msExitFullscreen) {
          (document as any).msExitFullscreen();
        }
      }
    } catch (err: any) {
      console.error(`Error with fullscreen: ${err.message}`);
    }
  };

  return (
    <button 
      onClick={(e) => {
        e.stopPropagation();
        toggleFullscreen();
      }}
      className={`p-3 rounded-2xl flex items-center gap-2 transition-all shadow-lg active:scale-95 scroll-mt-20 ${
        isFullscreen 
          ? 'bg-amber-100 text-amber-700 border border-amber-200' 
          : 'bg-slate-100/80 hover:bg-slate-200 text-slate-600 border border-slate-200'
      }`}
      title={isFullscreen ? "Sair Tela Cheia" : "Tela Cheia"}
    >
      {isFullscreen ? (
        <><Minimize size={20} /> <span className="text-[10px] font-black uppercase tracking-widest hidden sm:inline">Sair Fullscreen</span></>
      ) : (
        <><Maximize size={20} /> <span className="text-[10px] font-black uppercase tracking-widest hidden sm:inline">Fullscreen</span></>
      )}
    </button>
  );
};

// --- Notifications System ---
interface CustomToast {
  id: string;
  message: string;
  type: 'success' | 'error' | 'info';
}

const ToastContainer = ({ toasts, onRemove }: { toasts: CustomToast[], onRemove: (id: string) => void }) => {
  return (
    <div className="fixed top-6 right-6 z-[99999] flex flex-col gap-3 pointer-events-none">
      <AnimatePresence>
        {toasts.map((toast) => (
          <motion.div
            key={toast.id}
            initial={{ opacity: 0, x: 20, scale: 0.9 }}
            animate={{ opacity: 1, x: 0, scale: 1 }}
            exit={{ opacity: 0, scale: 0.9, transition: { duration: 0.2 } }}
            className={`
              pointer-events-auto p-4 rounded-2xl shadow-2xl flex items-center gap-4 min-w-[300px] max-w-md border
              ${toast.type === 'success' ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 
                toast.type === 'error' ? 'bg-red-50 border-red-100 text-red-800' : 
                'bg-blue-50 border-blue-100 text-blue-800'}
            `}
          >
            <div className={`
              w-10 h-10 rounded-xl flex items-center justify-center shrink-0
              ${toast.type === 'success' ? 'bg-emerald-500 text-white' : 
                toast.type === 'error' ? 'bg-red-500 text-white' : 
                'bg-blue-500 text-white'}
            `}>
              {toast.type === 'success' && <CheckCircle size={20} />}
              {toast.type === 'error' && <XCircle size={20} />}
              {toast.type === 'info' && <Info size={20} />}
            </div>
            <div className="flex-1">
              <p className="text-xs font-bold leading-tight">{toast.message}</p>
            </div>
            <button 
              onClick={() => onRemove(toast.id)}
              className="p-1 hover:bg-black/5 rounded-lg transition-colors"
            >
              <X size={16} />
            </button>
          </motion.div>
        ))}
      </AnimatePresence>
    </div>
  );
};

