// --- UI Helpers ---
enum OperationType {
  CREATE = 'create',
  UPDATE = 'update',
  DELETE = 'delete',
  LIST = 'list',
  GET = 'get',
  WRITE = 'write',
}

interface FirestoreErrorInfo {
  error: string;
  operationType: OperationType;
  path: string | null;
  authInfo: {
    userId?: string | null;
    email?: string | null;
    emailVerified?: boolean | null;
    isAnonymous?: boolean | null;
    tenantId?: string | null;
    providerInfo?: {
      providerId?: string | null;
      email?: string | null;
    }[];
  }
}

function handleFirestoreError(error: unknown, operationType: OperationType, path: string | null) {
  const errInfo: FirestoreErrorInfo = {
    error: error instanceof Error ? error.message : String(error),
    authInfo: {
      userId: auth.currentUser?.uid,
      email: auth.currentUser?.email,
      emailVerified: auth.currentUser?.emailVerified,
      isAnonymous: auth.currentUser?.isAnonymous,
      tenantId: auth.currentUser?.tenantId,
      providerInfo: auth.currentUser?.providerData?.map(provider => ({
        providerId: provider.providerId,
        email: provider.email,
      })) || []
    },
    operationType,
    path
  }
  console.error('Firestore Error: ', JSON.stringify(errInfo));
  throw new Error(JSON.stringify(errInfo));
}

export const getClientFromOrder = (clients: Client[], clientId: string, clientName?: string) => {
  if (!clientId) {
    if (clientName) {
      const foundByName = clients.find(c => c.name?.toLowerCase().trim() === clientName.toLowerCase().trim() || c.fantasyName?.toLowerCase().trim() === clientName.toLowerCase().trim());
      if (foundByName) return foundByName;
    }
    return undefined;
  }
  
  // 1. Match c.id directly
  let found = clients.find(c => c.id === clientId);
  if (found) return found;

  // 2. Match c.gestaoClickId with order's clientId (possibly cleaning up GC-CLI- prefix)
  const cleanGcId = clientId.replace('GC-CLI-', '');
  found = clients.find(c => c.gestaoClickId === cleanGcId || c.gestaoClickId === clientId);
  if (found) return found;

  // 3. Match by name
  if (clientName) {
    found = clients.find(c => c.name?.toLowerCase().trim() === clientName.toLowerCase().trim() || c.fantasyName?.toLowerCase().trim() === clientName.toLowerCase().trim());
    if (found) return found;
  }

  return undefined;
};

const logOrderActivity = async (orderId: string, title: string, description: string, icon: string = 'info') => {
  try {
    await addDoc(collection(db, 'orders', orderId, 'activity'), {
      title,
      description,
      icon,
      timestamp: new Date().toISOString(),
      user: auth.currentUser?.email || 'Sistema'
    });
  } catch (err) {
    handleFirestoreError(err, OperationType.WRITE, `orders/${orderId}/activity`);
  }
};

