  zipCode?: string;
  street?: string;
  number?: string;
  complement?: string;
  neighborhood?: string;
  city?: string;
  state?: string;
  municipalRegistration?: string;
  stateRegistration?: string;
  asaasCustomerId?: string;
  ibgeCode?: string;
  address: string;
  cep?: string;
  historyResetDate?: string;
