  const downloadAllLabelsPDF = async (capacity: number, forceFormat?: 'print' | 'download') => {
    if (!currentOrderInModal || !currentOrderInModal.items) return;
    
    let allNewLabels: any[] = [];
    const updatedItems = (currentOrderInModal.items || []).map((item: any) => {
      const unitsPerPack = item.unitsPerPack || 50;
      const packsPerBale = item.packsPerBale || capacity || 20;
      const readyQuantity = item.readyUnits !== undefined ? item.readyUnits : item.quantity;

      const totalPackages = Math.ceil(readyQuantity / unitsPerPack);
      const standardBales = Math.floor(totalPackages / packsPerBale);
      const leftoverPackages = totalPackages % packsPerBale;
      const totalLabels = standardBales + (leftoverPackages > 0 ? 1 : 0);
      
      const itemLabels: any[] = [];
      let labelIndex = 1;

      // Generate standard bales
      for (let i = 0; i < standardBales; i++) {
        const unitsInThisBale = packsPerBale * unitsPerPack;
        const labelId = `ORD${currentOrderInModal.id}-P${item.productId.substring(0, 5).toUpperCase()}-L${labelIndex}-Q${unitsInThisBale}`;
        itemLabels.push({
          id: labelId,
          orderId: currentOrderInModal.id,
          productId: item.productId,
          productName: item.productName,
          labelIndex: labelIndex,
          totalLabels: totalLabels,
          quantity: unitsInThisBale,
          packsCount: packsPerBale,
          isScanned: false,
          scannedAt: null
        });
        labelIndex++;
      }
      
      // Generate leftover bale
      if (leftoverPackages > 0) {
        const unitsInThisBale = leftoverPackages * unitsPerPack;
        const labelId = `ORD${currentOrderInModal.id}-P${item.productId.substring(0, 5).toUpperCase()}-L${labelIndex}-Q${unitsInThisBale}`;
        itemLabels.push({
          id: labelId,
          orderId: currentOrderInModal.id,
          productId: item.productId,
          productName: item.productName,
          labelIndex: labelIndex,
          totalLabels: totalLabels,
          quantity: unitsInThisBale,
          packsCount: leftoverPackages,
          isScanned: false,
          scannedAt: null
        });
      }
      
      allNewLabels = [...allNewLabels, ...itemLabels];

      return {
        ...item,
        unitsPerPack,
        readyUnits: readyQuantity,
        packsPerBale,
        generatedLabelsCount: totalLabels
      };
    });
    
    if (allNewLabels.length === 0) {
      notify('Nenhum item válido para gerar etiquetas.', 'error');
      return;
    }
    
    try {
      await onUpdateItem('orders', currentOrderInModal.id, { 
        labels: allNewLabels,
        items: updatedItems
      });

      // Update Stock for each item since we generated labels
      for (const item of updatedItems) {
        const readyUnits = item.readyUnits !== undefined ? item.readyUnits : item.quantity;
        const unitsPerPack = item.unitsPerPack || 50;
        const itemPackages = Math.ceil(readyUnits / unitsPerPack);

        const existingStock = (stock || []).find((s: any) => s.productId === item.productId && s.category === 'Produtos Acabados');
        if (existingStock) {
          await onUpdateItem('stock', existingStock.id, {
            quantity: itemPackages,
            unit: 'pct',
            lastUpdate: new Date().toISOString()
          });
        } else {
          await onAddItem('stock', {
            productId: item.productId,
            name: item.productName,
            category: 'Produtos Acabados',
            quantity: itemPackages,
            unit: 'pct',
            minQuantity: 0,
            location: 'Expedição',
            lastUpdate: new Date().toISOString()
          });
        }
      }

      notify(`Etiquetas geradas com sucesso para todo o pedido! (${allNewLabels.length} volumes)`, 'success');
      
      const configObj = labelConfig || { labelWidth: 50, labelHeight: 30, columnLayout: 'double', columnGap: 2, qrSize: 20, qrMarginRight: 5, outputMethod: 'print' };
      const doc = await generateLabelsPDFDoc(allNewLabels, currentOrderInModal, configObj);
      
      const method = forceFormat || configObj.outputMethod || 'print';
      if (method === 'print') {
        notify('Iniciando impressão direta das etiquetas...', 'info');
        triggerBrowserPrint(doc);
      } else {
        doc.save(`etiquetas-pedidocompleto-${currentOrderInModal.id}.pdf`);
        notify('PDF das etiquetas do pedido baixado!', 'success');
      }
    } catch (err: any) {
      console.error(err);
      notify(`Erro ao processar etiquetas do pedido completo: ${err.message || err}`, 'error');
    }
  };

