                  <input 
                    type="number" 
                    min={1}
                    value={packCapacityInput || ''}
                    onChange={(e) => {
                      const val = Number(e.target.value);
                      setPackCapacityInput(val > 0 ? val : 1);
                    }}
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-slate-800 font-bold focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm transition-all shadow-inner"
                  />
