  const handleAdminKeyPress = (key: string) => {
    if (key === 'CLEAR') {
      setAdminPassword('');
      setAdminPasswordError(false);
      return;
    }

    const nextPassword = adminPassword + key;
    if (nextPassword.length <= 4) {
      setAdminPassword(nextPassword);
      setAdminPasswordError(false);
      
      if (nextPassword.length === 4) {
        if (nextPassword === "1234") {
          setActiveTab('dashboard'); // Entra direto no dashboard
          setIsSidebarOpen(false); // Fecha a barra lateral
          setViewMode('admin');
          localStorage.setItem('souplastic_view_mode', 'admin');
          setShowAdminPasswordModal(false);
          setAdminPassword('');
        } else {
          setAdminPasswordError(true);
          // Auto clear error after a short delay for better UX
          setTimeout(() => {
            setAdminPassword('');
            setAdminPasswordError(false);
          }, 600);
        }
      }
    }
  };

