  const syncSpreadsheet = useCallback(async () => {
    setIsSyncingSpreadsheet(true);
    try {
      const data = await spreadsheetService.fetchInvoices();
      setSpreadsheetInvoices(data);

      // Query GestãoClick status for 'Processando' invoices instead of matching with spreadsheet
      const processandoInvoices = invoices.filter(inv => inv.status === 'Processando' && inv.notaasId);
      for (const inv of processandoInvoices) {
        try {
          const result = await gestaoClickService.checkStatus(inv.notaasId) as any;
          if (result.status === 'authorized' || result.status === 'success') {
            const invoiceRef = doc(db, 'invoices', inv.id);
            await updateDoc(invoiceRef, { 
              status: 'Autorizada',
              numero: result.number || result.numero || inv.numero || null,
              link: result.link_danfe || result.pdf_url || inv.link || null,
              updatedAt: serverTimestamp()
            });
          } else if (result.status === 'error') {
            const invoiceRef = doc(db, 'invoices', inv.id);
            await updateDoc(invoiceRef, { 
              status: 'Erro',
              message: result.message || 'Erro na emissão',
              updatedAt: serverTimestamp()
            });
          }
        } catch (e) {
          console.error(`Erro ao sincronizar status da nota ${inv.id} com GestãoClick:`, e);
        }
      }

    } catch (error) {
      console.error('Spreadsheet/GestaoClick sync error:', error);
    } finally {
      setIsSyncingSpreadsheet(false);
    }
  }, [invoices]);

  useEffect(() => {
    if (user) {
      syncSpreadsheet();
      const interval = setInterval(syncSpreadsheet, 60000); // 1 minute
      return () => clearInterval(interval);
    }
  }, [user, syncSpreadsheet]);

  useEffect(() => {
    const handleGlobalClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement | null;
      if (!target) return;
      
      // Determine if click corresponds to an interactive element
      const clickable = target.closest('button, [role="button"], a, input[type="submit"], input[type="button"], select, tr[onClick]');
      if (clickable) {
        if (typeof window !== 'undefined' && window.navigator && 'vibrate' in window.navigator) {
          try {
            window.navigator.vibrate(12);
          } catch (err) {
            // Ignore if vibration is blocked or unsupported on device
          }
        }
      }
    };

    document.addEventListener('click', handleGlobalClick);
    return () => {
      document.removeEventListener('click', handleGlobalClick);
    };
  }, []);

  // --- Sistema de Notificações Automáticas ---
  const remindersRef = useRef(reminders);
  const settingsRef = useRef(reminderSettings);
  useEffect(() => { remindersRef.current = reminders; }, [reminders]);
  useEffect(() => { settingsRef.current = reminderSettings; }, [reminderSettings]);

  useEffect(() => {
    if (!user) return;

    const checkReminders = async () => {
      const now = new Date();
      const currentReminders = remindersRef.current;
      const settings = settingsRef.current;

      if (!settings.telegramBotToken) return;

      const activeContacts = (settings.notificationContacts || []).filter(c => c.active && c.telegramChatId);
      if (activeContacts.length === 0) return;

      for (const rem of currentReminders) {
        if (rem.status !== 'Pendente') continue;

        try {
          const createdAt = new Date(rem.createdAt);
          const targetDate = new Date(`${rem.date}T${rem.time}`);
          const totalDurationMs = targetDate.getTime() - createdAt.getTime();
          const timeToTargetMs = targetDate.getTime() - now.getTime();
          
          let updatedRemindersSent = { ...(rem.remindersSent || {}) };
          let shouldUpdate = false;
          let message = "";

          // 1º Aviso: 50% do tempo (se o total for maior que 30 min)
          if (!updatedRemindersSent.first && totalDurationMs > 30 * 60000) {
             const halfTimeElapsed = timeToTargetMs <= (totalDurationMs / 2);
             if (halfTimeElapsed && timeToTargetMs > 2 * 3600000) { // Mas só se for maior que 2h (pra não encavalar)
                message = `⏰ <b>ALERTA 1/3 (PROXIMIDADE):</b>\n\nEstá chegando a hora! ${rem.type === 'TAREFA' ? 'Sua' : 'Seu'} <b>${rem.title}</b> será em breve.\n\n🕒 Horário: <b>${rem.time}</b>\n📅 Data: ${new Date(rem.date + 'T12:00:00').toLocaleDateString('pt-BR')}`;
                updatedRemindersSent.first = true;
                shouldUpdate = true;
             }
          }

          // 2º Aviso: 2 horas antes
          if (!updatedRemindersSent.second && timeToTargetMs <= 2 * 3600000 && timeToTargetMs > 5 * 60000) {
             message = `⏰ <b>ALERTA 2/3 (CONTAGEM REGRESSIVA):</b>\n\n<b>FALTAM 2 HORAS</b> para ${rem.type === 'TAREFA' ? 'a' : 'o'} <b>${rem.title}</b>.\n\n🕒 Realização às <b>${rem.time}</b>.`;
             updatedRemindersSent.first = true; // Garante que o primeiro tb esteja marcado
             updatedRemindersSent.second = true;
             shouldUpdate = true;
          }

          // 3º Aviso: Na hora!
          if (!updatedRemindersSent.atTime && timeToTargetMs <= 1 * 60000 && timeToTargetMs >= -30 * 60000) {
             message = `🚨 <b>ALERTA FINAL - AGORA!</b>\n\n📌 <b>${rem.title} (${rem.type})</b>\n\nO horário agendado (<b>${rem.time}</b>) chegou. Por favor, realize a ação agora e dê baixa no sistema.`;
             updatedRemindersSent.first = true;
             updatedRemindersSent.second = true;
             updatedRemindersSent.atTime = true;
             shouldUpdate = true;
          }

          if (shouldUpdate && message) {
            console.log(`Enviando lembrete automático via Telegram: ${rem.title}`);
            for (const contact of activeContacts) {
              const url = `https://api.telegram.org/bot${settings.telegramBotToken}/sendMessage`;
              await fetch(url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                  chat_id: contact.telegramChatId,
                  text: message,
                  parse_mode: 'HTML'
                })
              });
            }
            await updateDoc(doc(db, 'reminders', rem.id), { remindersSent: updatedRemindersSent });
          }
        } catch (e) {
          console.error("Erro no check de lembrete:", rem.id, e);
        }
      }
    };

    const interval = setInterval(checkReminders, 60000); // Checa a cada 1 minuto
    checkReminders(); // Checa imediatamente ao montar
    return () => clearInterval(interval);
  }, [user]);

